--Q111

--Find the total revenue generated by each product.

--version 1
SELECT
    product_id,
    ROUND(SUM(
        quantity * unit_price *
        (1 - discount_percent / 100.0)
    ),2) AS total_revenue
FROM order_items
GROUP BY product_id
ORDER BY product_id;

--version 2
SELECT
    p.product_id,
    p.product_name,
    ROUND(SUM(
        oi.quantity * oi.unit_price *
        (1 - oi.discount_percent / 100.0)
    ),2) AS total_revenue
FROM products p
JOIN order_items oi
    ON p.product_id = oi.product_id
GROUP BY p.product_id, p.product_name
ORDER BY p.product_id;